head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.tac1_ontabclick = function(tabID, idx) {
    //		mf_tabControl1.getFrame(0).getDisabled()
};
scwin.trigger1_onclick = function(e) {
    tabControl1.disableTab(1);
};
scwin.trigger2_onclick = function(e) {
    tabControl1.enableTab(1);
};
scwin.trigger3_onclick = function(e) {
    if (tabControl1.getWindow(1).gridView1.getColumnVisible(1)) {
        tabControl1.getWindow(1).gridView1.setColumnVisible(1, false);
    } else {
        tabControl1.getWindow(1).gridView1.setColumnVisible(1, true)
    }
};
scwin.trigger4_onclick = function(e) {
    var options = {
        useModalDisable: "true"
    }
    tabControl1.getWindow(1).gridView1.advancedExcelUpload(options);
};
scwin.trigger5_onclick = function(e) {
    var tabId = tabControl1.addTab("content2", {
        label: "dd",
        closable: true,
        disabled: false,
        openAction: "exist"
    }, {
        src: "gridView_setColumnVisible_WESD-751_(WSQ-4801)_childTab_frame1.xml",
        alwaysDraw: false
    });
    tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabId));
};
scwin.trigger6_onclick = function(e) {
    var tabId = tabControl1.addTab("content3", {
        label: "cc",
        closable: true,
        disabled: false,
        openAction: "exist"
    }, {
        src: "gridView_setColumnVisible_WESD-751_(WSQ-4801)_childTab_frame2.xml",
        alwaysDraw: false
    });
    tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabId));
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
